from dataclasses import dataclass, replace

@dataclass
class Case:
    case_id: str
    status: str

class SloppyRepo:
    def __init__(self):
        self.rows = {}
    def add(self, c):
        self.rows[c.case_id] = c
    def get(self, i):
        return self.rows.get(i)
    def save(self, c):
        self.rows[c.case_id] = c

class CopyingRepo:
    def __init__(self):
        self.rows = {}
    def add(self, c):
        self.rows[c.case_id] = replace(c)
    def get(self, i):
        r = self.rows.get(i)
        return replace(r) if r else None
    def save(self, c):
        self.rows[c.case_id] = replace(c)

def close_forgetting_save(repo, i):
    case = repo.get(i)
    case.status = "closed"  # repo.save(case) is missing

